fn resurrect_monsters3_onmymobdead_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_map_s = Val::from("");
    let mut l_mob_dead_num = Val::from(0);
    let mut l_mob_ran = Val::from(0);
    l_map_s = ctx.call(Function::InstanceMapName, vec![Val::from("1@orcs")])?;
    l_mob_dead_num = (Val::from(15).try_sub(ctx.call(
        Function::MobCount,
        vec![
            l_map_s.clone(),
            (ctx.call(Function::InstanceNpcName, vec![Val::from("#Resurrect Monsters3")])? + Val::from("::OnMyMobDead")),
        ],
    )?)?);
    l_mob_ran = ctx.call(Function::Rand, vec![Val::from(1), Val::from(30)])?;
    if l_mob_ran.clone().number()? > 29 {
        if l_mob_dead_num.clone().number()? > 0 {
            ctx.call(
                Function::Monster,
                vec![
                    l_map_s.clone(),
                    Val::from(0),
                    Val::from(0),
                    Val::from("Orc Archer"),
                    Val::from(1189),
                    l_mob_dead_num.clone(),
                    (ctx.call(Function::InstanceNpcName, vec![Val::from("#Resurrect Monsters3")])? + Val::from("::OnMyMobDead")),
                ],
            )?;
        }
    } else {
        if (l_mob_ran.clone().number()? > 26 && l_mob_ran.clone().number()? < 30) {
            if l_mob_dead_num.clone().number()? > 0 {
                ctx.call(
                    Function::AreaMonster,
                    vec![
                        l_map_s.clone(),
                        Val::from(43),
                        Val::from(155),
                        Val::from(47),
                        Val::from(159),
                        Val::from("Orc Archer"),
                        Val::from(1189),
                        l_mob_dead_num.clone(),
                        (ctx.call(Function::InstanceNpcName, vec![Val::from("#Resurrect Monsters3")])? + Val::from("::OnMyMobDead")),
                    ],
                )?;
                if ctx.call(Function::Rand, vec![Val::from(1), Val::from(3)])? == 3 {
                    ctx.call(
                        Function::MapAnnounce,
                        vec![
                            l_map_s.clone(),
                            Val::from("High Orc: Attack them from behind! Cut off their support!"),
                            ctx.constant("BC_MAP")?,
                            Val::from("0xff4444"),
                        ],
                    )?;
                }
            }
        } else {
            if l_mob_dead_num.clone().number()? > 0 {
                ctx.call(
                    Function::AreaMonster,
                    vec![
                        l_map_s.clone(),
                        Val::from(17),
                        Val::from(187),
                        Val::from(27),
                        Val::from(177),
                        Val::from("Orc Archer"),
                        Val::from(1189),
                        l_mob_dead_num.clone(),
                        (ctx.call(Function::InstanceNpcName, vec![Val::from("#Resurrect Monsters3")])? + Val::from("::OnMyMobDead")),
                    ],
                )?;
            }
        }
    }
    return Err(Stop::End);
}

