#[derive(Clone, Copy, Debug)]
enum B1Area1Step {
    Start,
    OnInstanceInit,
    OnEnable,
    OnTouch,
    OnContinue,
    OnTimer10300,
    OnTimer18700,
}

fn b1_area_1_run(ctx: &Ctx, mut step: B1Area1Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            B1Area1Step::Start => {
                step = B1Area1Step::OnInstanceInit;
                continue 'machine;
            }
            B1Area1Step::OnInstanceInit => {
                ctx.call(
                    Function::DisableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("B1 Area 1")])?],
                )?;
                return Err(Stop::End);
            }
            B1Area1Step::OnEnable => {
                ctx.call(
                    Function::EnableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("B1 Area 1")])?],
                )?;
                ctx.call(
                    Function::AreaMonster,
                    vec![
                        ctx.call(Function::InstanceMapName, vec![Val::from("1@orcs")])?,
                        Val::from(103),
                        Val::from(105),
                        Val::from(109),
                        Val::from(111),
                        Val::from("Enchanted Orc"),
                        Val::from(1023),
                        Val::from(1),
                        (ctx.call(Function::InstanceNpcName, vec![Val::from("B1 Area Mobs")])? + Val::from("::OnMyMobDead1")),
                    ],
                )?;
                return Err(Stop::End);
            }
            B1Area1Step::OnTouch => {
                ctx.call(
                    Function::Warp,
                    vec![
                        ctx.call(Function::InstanceMapName, vec![Val::from("1@orcs")])?,
                        Val::from(168),
                        Val::from(130),
                    ],
                )?;
                return Err(Stop::End);
            }
            B1Area1Step::OnContinue => {
                ctx.call(
                    Function::DoNpcEvent,
                    vec![(ctx.call(Function::InstanceNpcName, vec![Val::from("B1 Area 2")])? + Val::from("::OnEnable"))],
                )?;
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            B1Area1Step::OnTimer10300 => {
                ctx.call(Function::MapAnnounce, vec![ctx.call(Function::InstanceMapName, vec![Val::from("1@orcs")])?, Val::from("Kruger's Whisper: The Orcs here used to be my companions. They just lost their will ever since the Orc Shaman started to control them with her magic."), ctx.constant("BC_MAP")?, Val::from("0xff4499")])?;
                return Err(Stop::End);
            }
            B1Area1Step::OnTimer18700 => {
                ctx.call(Function::MapAnnounce, vec![ctx.call(Function::InstanceMapName, vec![Val::from("1@orcs")])?, Val::from("Kruger's Whisper: There's nothing we can do but to defeat the Orc Shaman if we want to save the remaining tribes."), ctx.constant("BC_MAP")?, Val::from("0xff4499")])?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn b1_area_1(ctx: &Ctx) -> Script {
    b1_area_1_run(ctx, B1Area1Step::Start, Vec::new()).map(|_| ())
}

