fn s_2resurrect_monsters1_onmymobdead_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_map_s = Val::from("");
    let mut l_mob_dead_num = Val::from(0);
    let mut l_mob_ran = Val::from(0);
    l_map_s = ctx.call(Function::InstanceMapName, vec![Val::from("2@orcs")])?;
    l_mob_dead_num = (Val::from(30).try_sub(ctx.call(
        Function::MobCount,
        vec![
            l_map_s.clone(),
            (ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters1")])? + Val::from("::OnMyMobDead")),
        ],
    )?)?);
    if l_mob_dead_num.clone().number()? > 0 {
        l_mob_ran = ctx.call(Function::Rand, vec![Val::from(1), Val::from(30)])?;
        if l_mob_ran.clone().number()? > 29 {
            ctx.call(
                Function::Monster,
                vec![
                    l_map_s.clone(),
                    Val::from(0),
                    Val::from(0),
                    Val::from("Vengeful Orc"),
                    Val::from(1152),
                    l_mob_dead_num.clone(),
                    (ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters1")])? + Val::from("::OnMyMobDead")),
                ],
            )?;
        } else {
            if (l_mob_ran.clone().number()? > 28 && l_mob_ran.clone().number()? < 30) {
                ctx.call(
                    Function::Monster,
                    vec![
                        l_map_s.clone(),
                        Val::from(0),
                        Val::from(0),
                        Val::from("High Orc"),
                        Val::from(1213),
                        l_mob_dead_num.clone(),
                        (ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters1")])? + Val::from("::OnMyMobDead")),
                    ],
                )?;
            } else {
                if (l_mob_ran.clone().number()? > 26 && l_mob_ran.clone().number()? < 29) {
                    ctx.call(
                        Function::AreaMonster,
                        vec![
                            l_map_s.clone(),
                            Val::from(157),
                            Val::from(112),
                            Val::from(167),
                            Val::from(122),
                            Val::from("High Orc"),
                            Val::from(1213),
                            l_mob_dead_num.clone(),
                            (ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters1")])? + Val::from("::OnMyMobDead")),
                        ],
                    )?;
                    if ctx.call(Function::Rand, vec![Val::from(1), Val::from(10)])? == 9 {
                        ctx.call(
                            Function::MapAnnounce,
                            vec![
                                l_map_s.clone(),
                                Val::from("Warning: High Orcs are gathering near area 3."),
                                ctx.constant("BC_MAP")?,
                                Val::from("0xff4444"),
                            ],
                        )?;
                    }
                } else {
                    ctx.call(
                        Function::AreaMonster,
                        vec![
                            l_map_s.clone(),
                            Val::from(173),
                            Val::from(13),
                            Val::from(183),
                            Val::from(23),
                            Val::from("High Orc"),
                            Val::from(1213),
                            l_mob_dead_num.clone(),
                            (ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters1")])? + Val::from("::OnMyMobDead")),
                        ],
                    )?;
                    if ctx.call(Function::Rand, vec![Val::from(1), Val::from(5)])? == 3 {
                        ctx.call(
                            Function::MapAnnounce,
                            vec![
                                l_map_s.clone(),
                                Val::from("Caution: The Forces have started to concentrate at the Shaman's Altar."),
                                ctx.constant("BC_MAP")?,
                                Val::from("0x77ff77"),
                            ],
                        )?;
                    }
                    if ctx.call(Function::Rand, vec![Val::from(1), Val::from(70)])? == 50 {
                        ctx.call(Function::InitNpcTimer, vec![])?;
                    }
                }
            }
        }
    }
    return Err(Stop::End);
}

