fn torch_1_1_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_id: Vec<Val> = Vec::new();
    if ctx
        .call(
            Function::IsPartyLeader,
            vec![ctx.call(Function::GetCharacterId, vec![Val::from(1)])?],
        )?
        .loosely_equals(&Val::from(0))
    {
        return Err(Stop::End);
    }
    ctx.call(Function::ProgressBar, vec![Val::from("ffff00"), Val::from(5)])?;
    let base = Val::from(0).number()?;
    runtime::local_set(
        &mut l_id,
        &Val::from(base + 0),
        runtime::atoi(&runtime::charat(
            &ctx.call(Function::StrNpcInfo, vec![Val::from(2)])?,
            &Val::from(0),
        )?),
        false,
    );
    runtime::local_set(
        &mut l_id,
        &Val::from(base + 1),
        runtime::atoi(&runtime::charat(
            &ctx.call(Function::StrNpcInfo, vec![Val::from(2)])?,
            &Val::from(2),
        )?),
        false,
    );
    if runtime::local_get(&l_id, &Val::from(1), false) == 4 {
        ctx.call(
            Function::DoNpcEvent,
            vec![
                (ctx.call(
                    Function::InstanceNpcName,
                    vec![(Val::from("#Warp2-") + runtime::local_get(&l_id, &Val::from(0), false))],
                )? + Val::from("::OnEnable")),
            ],
        )?;
    } else {
        ctx.call(
            Function::DoNpcEvent,
            vec![
                (ctx.call(
                    Function::InstanceNpcName,
                    vec![
                        (((Val::from("Torch#") + runtime::local_get(&l_id, &Val::from(0), false)) + Val::from("-"))
                            + (runtime::local_get(&l_id, &Val::from(1), false) + Val::from(1))),
                    ],
                )? + Val::from("::OnEnable")),
            ],
        )?;
    }
    ctx.call(Function::InitNpcTimer, vec![])?;
    ctx.call(Function::DisableNpc, vec![])?;
    return Err(Stop::End);
}

