#[derive(Clone, Copy, Debug)]
enum Warp21Step {
    Start,
    OnInstanceInit,
    OnEnable,
    OnContinue,
    OnTimer10000,
    OnTouch,
}

fn warp2_1_run(ctx: &Ctx, mut step: Warp21Step, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_map_s = Val::from("");
    'machine: loop {
        match step {
            Warp21Step::Start => {
                step = Warp21Step::OnInstanceInit;
                continue 'machine;
            }
            Warp21Step::OnInstanceInit => {
                ctx.call(
                    Function::DisableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("#Warp2-1")])?],
                )?;
                return Err(Stop::End);
            }
            Warp21Step::OnEnable => {
                l_map_s = ctx.call(Function::InstanceMapName, vec![Val::from("2@orcs")])?;
                ctx.call(
                    Function::Monster,
                    vec![
                        l_map_s.clone(),
                        Val::from(109),
                        Val::from(156),
                        Val::from("Safeguard Chief"),
                        Val::from(1981),
                        Val::from(1),
                        (ctx.call(Function::InstanceNpcName, vec![Val::from("#Mobs Control")])? + Val::from("::OnMyMobDead1")),
                    ],
                )?;
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        l_map_s.clone(),
                        Val::from("The Chief Orc of Safeguards: Oh!! Looks like I have company. Defeat me if you can!!"),
                        ctx.constant("BC_MAP")?,
                        Val::from("0xff8888"),
                    ],
                )?;
                return Err(Stop::End);
            }
            Warp21Step::OnContinue => {
                ctx.call(
                    Function::EnableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("#Warp2-1")])?],
                )?;
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            Warp21Step::OnTimer10000 => {
                ctx.call(
                    Function::AreaMonster,
                    vec![
                        ctx.call(Function::InstanceMapName, vec![Val::from("2@orcs")])?,
                        Val::from(28),
                        Val::from(158),
                        Val::from(40),
                        Val::from(170),
                        Val::from("Safeguard Chief"),
                        Val::from(1981),
                        Val::from(1),
                        (ctx.call(Function::InstanceNpcName, vec![Val::from("#Mobs Control")])? + Val::from("::OnMyMobDead1")),
                    ],
                )?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            Warp21Step::OnTouch => {
                ctx.call(
                    Function::Warp,
                    vec![
                        ctx.call(Function::InstanceMapName, vec![Val::from("2@orcs")])?,
                        Val::from(47),
                        Val::from(93),
                    ],
                )?;
                return Err(Stop::End);
            }
        }
    }
}

