fn boss_control_onmymobdead_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_map_s = Val::from("");
    let mut l_mob_ran = Val::from(0);
    ctx.call(
        Function::DoNpcEvent,
        vec![(ctx.call(Function::InstanceNpcName, vec![Val::from("Kruger#")])? + Val::from("::OnEnable"))],
    )?;
    l_map_s = ctx.call(Function::InstanceMapName, vec![Val::from("2@orcs")])?;
    l_mob_ran = ctx.call(Function::Rand, vec![Val::from(1), Val::from(5)])?;
    if l_mob_ran.clone() == 1 {
        ctx.call(
            Function::MapAnnounce,
            vec![
                l_map_s.clone(),
                Val::from("Shaman Cargalache: How... How could this be... How could someone like you...!!"),
                ctx.constant("BC_MAP")?,
                Val::from("0xffff00"),
            ],
        )?;
    } else {
        if l_mob_ran.clone() == 2 {
            ctx.call(
                Function::MapAnnounce,
                vec![
                    l_map_s.clone(),
                    Val::from("Shaman Cargalache: How is it that I've been overpowered by mere humans!"),
                    ctx.constant("BC_MAP")?,
                    Val::from("0xffff00"),
                ],
            )?;
        } else {
            if l_mob_ran.clone() == 3 {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        l_map_s.clone(),
                        Val::from("Shaman Cargalache: This... This can't be the end..."),
                        ctx.constant("BC_MAP")?,
                        Val::from("0xffff00"),
                    ],
                )?;
            } else {
                if l_mob_ran.clone() == 4 {
                    ctx.call(
                        Function::MapAnnounce,
                        vec![
                            l_map_s.clone(),
                            Val::from("Shaman Cargalache: I... Can't die... Yet...!"),
                            ctx.constant("BC_MAP")?,
                            Val::from("0xffff00"),
                        ],
                    )?;
                } else {
                    ctx.call(
                        Function::MapAnnounce,
                        vec![
                            l_map_s.clone(),
                            Val::from("Shaman Cargalache: Defeated by these fools... It can't be happening...!"),
                            ctx.constant("BC_MAP")?,
                            Val::from("0xffff00"),
                        ],
                    )?;
                }
            }
        }
    }
    ctx.call(
        Function::DoNpcEvent,
        vec![(ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters1")])? + Val::from("::OnDisable"))],
    )?;
    ctx.call(
        Function::DoNpcEvent,
        vec![(ctx.call(Function::InstanceNpcName, vec![Val::from("#2Resurrect Monsters3")])? + Val::from("::OnDisable"))],
    )?;
    ctx.call(
        Function::DoNpcEvent,
        vec![(ctx.call(Function::InstanceNpcName, vec![Val::from("#Warp Outside Orc Dun")])? + Val::from("::OnEnable"))],
    )?;
    return Err(Stop::End);
}

pub fn boss_control_onmymobdead(ctx: &Ctx) -> Script {
    boss_control_onmymobdead_body(ctx, Vec::new()).map(|_| ())
}

#[derive(Clone, Copy, Debug)]
enum WarpOutsideOrcDunStep {
    Start,
    OnInstanceInit,
    OnEnable,
    OnTouch,
}

fn warp_outside_orc_dun_run(ctx: &Ctx, mut step: WarpOutsideOrcDunStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            WarpOutsideOrcDunStep::Start => {
                step = WarpOutsideOrcDunStep::OnInstanceInit;
                continue 'machine;
            }
            WarpOutsideOrcDunStep::OnInstanceInit => {
                ctx.call(
                    Function::DisableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("#Warp Outside Orc Dun")])?],
                )?;
                return Err(Stop::End);
            }
            WarpOutsideOrcDunStep::OnEnable => {
                ctx.call(
                    Function::EnableNpc,
                    vec![ctx.call(Function::InstanceNpcName, vec![Val::from("#Warp Outside Orc Dun")])?],
                )?;
                return Err(Stop::End);
            }
            WarpOutsideOrcDunStep::OnTouch => {
                ctx.call(Function::Warp, vec![Val::from("gef_fild10"), Val::from(240), Val::from(197)])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn warp_outside_orc_dun(ctx: &Ctx) -> Script {
    warp_outside_orc_dun_run(ctx, WarpOutsideOrcDunStep::Start, Vec::new()).map(|_| ())
}

